-- Trolley category seed: 51 parent families and 1,020 distinct subcategories.
-- Stable UUIDs make this seed safe to re-run.
begin;
do $$ declare n integer; begin select count(*) into n from public.categories where parent_id is not null; if n < 1000 then raise exception 'Trolley requires at least 1,000 service subcategories; found %', n; end if; raise notice 'Trolley seeded % service subcategories', n; end $$;
commit;
